constexpr size_t kMaxNotifyQueueSize = 4096;

#pragma pack(push, 1)
struct CtrlMsgHeader {
  uint32_t magic;
  uint64_t body_size;
};
#pragma pack(pop)

enum class CtrlMsgType : int32_t {
  kCreateChannelReq = 1,
  kCreateChannelResp = 2,
  kGetRemoteMemReq = 3,
  kGetRemoteMemResp = 4,
  kGetEndpointInfoReq = 5,
  kGetEndpointInfoResp = 6,
  kGetCacheTableReq = 7,
  kGetCacheTableResp = 8,
  kMatchEndpointReq = 9,
  kMatchEndpointResp = 10,
  kDestroyChannelReq = 11,
  kNotify = 12,
  kNotifyAck = 13,
  kHeartBeat = 14,
  kGetMemInfoReq = 15,
  kGetMemInfoResp = 16,
  kEnd
};

struct CtrlMsg {
  CtrlMsgType msg_type;
  std::string msg;
};

struct MatchEndpointReq {
  EndpointDesc dst;
};

struct MatchEndpointResp {
  Status result;
  uint64_t dst_ep_handle = 0UL;
  uint32_t port;
  uint64_t channel_index = 0UL;  ///< server端生成的进程级channel索引，用于两端构建一致的channelName
};

struct CreateChannelReq {
  EndpointDesc src;
  uint64_t dst_ep_handle = 0UL;
  uint8_t tc;
  uint8_t sl;
  uint32_t retry_cnt = 0U;
  uint32_t retry_interval = 0U;
  uint64_t channel_index = 0UL;
  uint8_t qos = 0U;
  uint32_t timeout_ms = 0U;
};

struct CreateChannelResp {
  Status result;
};

struct GetRemoteMemReq {
  uint64_t dst_ep_handle = 0UL;
};

struct HixlMemDesc {
  CommMem mem;
  bool is_imported = false;
  std::string tag;
  void *export_desc = nullptr;
  uint32_t export_len = 0U;
  void *registered_dev_mem = nullptr;  // 记录host内存注册的device内存，当前用于UBoE/UB_RTP等映射协议
};

struct GetRemoteMemResp {
  Status result;
  std::vector<HixlMemDesc> mem_descs;
};

struct DestroyChannelReq {
  uint64_t endpoint_handle;
  uint64_t channel_handle;
};

struct NotifyMsg {
  std::string name;
  std::string notify_msg;
};

using CtrlMsgPtr = std::shared_ptr<CtrlMsg>;
using MsgProcessor = std::function<Status(int32_t fd, const char *msg, uint64_t msg_len)>;
}  // namespace hixl

namespace hixl {
HixlStatus HixlCSServerRegProc(HixlServerHandle server_handle, hixl::CtrlMsgType msg_type, hixl::MsgProcessor proc);
}
#endif  // CANN_HIXL_SRC_HIXL_CS_HIXL_CTRL_MSG_H_

