10	
11	#include "conn_msg_handler.h"
12	#include <cinttypes>
13	#include <cstring>
14	#include <vector>
15	#include <securec.h>
16	#include "common/ctrl_msg_plugin.h"
17	
18	namespace {
19	hixl::Status SendHeaderTypeBody(int32_t socket, const hixl::CtrlMsgHeader &header, hixl::CtrlMsgType msg_type,
20	                                const void *body, uint64_t body_size) {
21	  HIXL_LOGI("Start sending header, type and body. socket: %d, body_size: %lu", socket, body_size);
22	  HIXL_CHK_STATUS_RET(hixl::CtrlMsgPlugin::Send(socket, &header, static_cast<uint64_t>(sizeof(header))));
23	  HIXL_CHK_STATUS_RET(hixl::CtrlMsgPlugin::Send(socket, &msg_type, static_cast<uint64_t>(sizeof(msg_type))));
24	  HIXL_CHK_STATUS_RET(hixl::CtrlMsgPlugin::Send(socket, body, body_size));
25	  HIXL_LOGI("Successfully sent header, type and body.");
26	  return hixl::SUCCESS;
27	}
28	
29	hixl::Status RecvAndCheckHeader(int32_t socket, uint64_t expect_body_size, hixl::CtrlMsgHeader &header,
30	                                uint32_t timeout_ms) {
31	  HIXL_LOGI("Start receiving and checking header. socket: %d, expect_body_size: %lu", socket, expect_body_size);
32	  HIXL_CHK_STATUS_RET(hixl::CtrlMsgPlugin::Recv(socket, &header, static_cast<uint32_t>(sizeof(header)), timeout_ms),
33	                      "Failed to recv header. socket=%d, len=%lu, timeout=%u ms", socket, sizeof(header), timeout_ms);
34	  HIXL_LOGD("Header received. magic: 0x%X, body_size: %lu", header.magic, header.body_size);
35	  HIXL_CHK_BOOL_RET_STATUS(header.magic == hixl::kMagicNumber, hixl::PARAM_INVALID,
36	                           "Invalid magic for CreateChannelResp, expect:0x%X, actual:0x%X", hixl::kMagicNumber,
37	                           header.magic);
38	  HIXL_CHK_BOOL_RET_STATUS(header.body_size == expect_body_size, hixl::PARAM_INVALID,
39	                           "Invalid body_size in CreateChannelResp, expect:%" PRIu64 ", actual:%" PRIu64,
40	                           expect_body_size, header.body_size);
41	  return hixl::SUCCESS;
42	}
43	
44	hixl::Status RecvBody(int32_t socket, uint64_t body_size, std::vector<uint8_t> &body, uint32_t timeout_ms) {
45	  HIXL_LOGI("Start receiving body. socket: %d, body_size: %lu", socket, body_size);
46	  body.resize(static_cast<size_t>(body_size));
47	  HIXL_CHK_STATUS_RET(hixl::CtrlMsgPlugin::Recv(socket, body.data(), static_cast<uint32_t>(body_size), timeout_ms));
48	  HIXL_LOGI("Successfully received body.");
49	  return hixl::SUCCESS;
50	}
51	
52	hixl::Status ParseMsgType(const std::vector<uint8_t> &body, size_t &offset, hixl::CtrlMsgType &msg_type,
53	                          hixl::CtrlMsgType expected) {
54	  if (offset + sizeof(hixl::CtrlMsgType) > body.size()) {
55	    HIXL_LOGE(hixl::PARAM_INVALID, "ctrl resp body too short for msg_type, offset=%zu, need=%zu, body=%zu", offset,
56	              offset + sizeof(hixl::CtrlMsgType), body.size());
57	    return hixl::PARAM_INVALID;
58	  }
59	
60	  const void *src = static_cast<const void *>(body.data() + offset);
61	  errno_t rc = memcpy_s(&msg_type, sizeof(msg_type), src, sizeof(msg_type));
62	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, hixl::FAILED, "memcpy_s msg_type failed, rc=%d", static_cast<int32_t>(rc));
63	
64	  offset += sizeof(hixl::CtrlMsgType);
65	  HIXL_CHK_BOOL_RET_STATUS(msg_type == expected, hixl::PARAM_INVALID, "Unexpected msg_type=%d in ctrl resp, expect=%d",
66	                           static_cast<int32_t>(msg_type), static_cast<int32_t>(expected));
67	  return hixl::SUCCESS;
68	}
69	
70	hixl::Status ParseCreateChannelResp(const std::vector<uint8_t> &body, size_t offset, hixl::CreateChannelResp &resp) {
71	  if (offset + sizeof(hixl::CreateChannelResp) > body.size()) {
72	    HIXL_LOGE(hixl::PARAM_INVALID, "CreateChannelResp body too short, offset=%zu, need=%zu, body=%zu", offset,
73	              offset + sizeof(hixl::CreateChannelResp), body.size());
74	    return hixl::PARAM_INVALID;
75	  }
76	
77	  const void *src = static_cast<const void *>(body.data() + offset);
78	  errno_t rc = memcpy_s(&resp, sizeof(resp), src, sizeof(resp));
79	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, hixl::FAILED, "memcpy_s createChannelResp failed, rc=%d",
80	                           static_cast<int32_t>(rc));
81	  HIXL_LOGD("Parsed CreateChannelResp. result: %d", static_cast<int32_t>(resp.result));
82	  return hixl::SUCCESS;
83	}
84	
85	hixl::Status ParseMatchEndpointResp(const std::vector<uint8_t> &body, size_t offset, hixl::MatchEndpointResp &resp) {
86	  if (offset + sizeof(hixl::MatchEndpointResp) > body.size()) {
87	    HIXL_LOGE(hixl::PARAM_INVALID, "MatchEndpointResp body too short, offset=%zu, need=%zu, body=%zu", offset,
88	              offset + sizeof(hixl::MatchEndpointResp), body.size());
89	    return hixl::PARAM_INVALID;
90	  }
91	  const void *src = static_cast<const void *>(body.data() + offset);
92	  errno_t rc = memcpy_s(&resp, sizeof(resp), src, sizeof(resp));
93	  HIXL_CHK_BOOL_RET_STATUS(rc == EOK, hixl::FAILED, "memcpy_s MatchEndpointResp failed, rc=%d",
94	                           static_cast<int32_t>(rc));
95	  HIXL_LOGD("Parsed MatchEndpointResp. result: %d, dst_ep_handle: %lu, channel_index: %" PRIu64,
96	            static_cast<int32_t>(resp.result), resp.dst_ep_handle, resp.channel_index);
97	  return hixl::SUCCESS;
98	}
99	
100	hixl::Status RecvMatchEndpointHandleResponse(int32_t socket, uint64_t &remote_endpoint_handle,
101	                                             uint32_t &remote_listen_port, uint64_t &channel_index,
102	                                             uint32_t timeout_ms) {
103	  const uint64_t expect_body_size = static_cast<uint64_t>(sizeof(hixl::CtrlMsgType) + sizeof(hixl::MatchEndpointResp));
104	
105	  hixl::CtrlMsgHeader header{};
106	  HIXL_CHK_STATUS_RET(RecvAndCheckHeader(socket, expect_body_size, header, timeout_ms));
107	
108	  std::vector<uint8_t> body;
109	  HIXL_CHK_STATUS_RET(RecvBody(socket, header.body_size, body, timeout_ms));
110	
111	  size_t offset = 0U;
112	  hixl::CtrlMsgType msg_type{};
113	  HIXL_CHK_STATUS_RET(ParseMsgType(body, offset, msg_type, hixl::CtrlMsgType::kMatchEndpointResp));
114	
115	  hixl::MatchEndpointResp resp{};
116	  HIXL_CHK_STATUS_RET(ParseMatchEndpointResp(body, offset, resp));
117	
118	  HIXL_CHK_BOOL_RET_STATUS(resp.result == hixl::SUCCESS, hixl::FAILED,
119	                           "MatchEndpointResp result not SUCCESS, result=%u", static_cast<uint32_t>(resp.result));
120	  remote_endpoint_handle = resp.dst_ep_handle;
121	  remote_listen_port = resp.port;
122	  channel_index = resp.channel_index;
123	  HIXL_LOGI(
124	      "MatchEndpointResp check passed. remote_endpoint_handle set to %lu, remote_listen_port=%u, "
