89	hixl::Status ParseResultAndGetArray(const nlohmann::json &j, const nlohmann::json *&arr_out) {
90	  try {
91	    if (!j.contains("result")) {
92	      HIXL_LOGE(hixl::PARAM_INVALID, "[HixlClient] GetRemoteMemResp json has no field 'result'");
93	      return hixl::PARAM_INVALID;
94	    }
95	
96	    hixl::Status result = static_cast<hixl::Status>(j["result"].get<uint32_t>());
97	    if (result != hixl::SUCCESS) {
98	      HIXL_LOGE(result, "[HixlClient] GetRemoteMemResp result not SUCCESS, result=%u", static_cast<uint32_t>(result));
99	      return result;
100	    }
101	
102	    if (!j.contains("mem_descs") || !j["mem_descs"].is_array()) {
103	      HIXL_LOGE(hixl::PARAM_INVALID, "[HixlClient] GetRemoteMemResp json 'mem_descs' is missing or not array");
104	      return hixl::PARAM_INVALID;
105	    }
106	
107	    arr_out = &j["mem_descs"];
108	    return hixl::SUCCESS;
109	  } catch (const nlohmann::json::exception &e) {
110	    HIXL_LOGE(hixl::PARAM_INVALID, "[HixlClient] JSON error in ParseResultAndGetArray: %s", e.what());
111	    return hixl::PARAM_INVALID;
112	  } catch (...) {
113	    HIXL_LOGE(hixl::FAILED, "[HixlClient] Unknown error in ParseResultAndGetArray");
114	    return hixl::FAILED;
