121	      HIXL_LOGE(hixl::PARAM_INVALID, "[HixlClient] GetRemoteMemResp.mem missing 'type' / 'addr' / 'size'");
122	      return hixl::PARAM_INVALID;
123	    }
124	
125	    mem.type = static_cast<CommMemType>(j_mem["type"].get<uint32_t>());
126	    const uint64_t addr_u64 = j_mem["addr"].get<uint64_t>();
127	    mem.addr = reinterpret_cast<void *>(static_cast<uintptr_t>(addr_u64));
128	    mem.size = j_mem["size"].get<uint64_t>();
129	    return hixl::SUCCESS;
130	  } catch (const nlohmann::json::exception &e) {
131	    HIXL_LOGE(hixl::PARAM_INVALID, "[HixlClient] JSON error in ParseMemObject: %s", e.what());
132	    return hixl::PARAM_INVALID;
