139	hixl::Status FillExportDescFromJsonField(const nlohmann::json &j_export, hixl::HixlMemDesc &desc) {
140	  if (desc.export_desc != nullptr) {
141	    std::free(desc.export_desc);
142	    desc.export_desc = nullptr;
143	  }
144	  desc.export_len = 0U;
145	  if (!j_export.is_array()) {
146	    HIXL_LOGE(hixl::PARAM_INVALID, "[HixlClient] export_desc must be array");
147	    return hixl::PARAM_INVALID;
148	  }
149	  const size_t n = j_export.size();
150	  if (n == 0U) {
151	    return hixl::SUCCESS;
152	  }
153	  void *buf = std::malloc(n);
154	  HIXL_CHK_BOOL_RET_STATUS(buf != nullptr, hixl::FAILED,
155	                           "[HixlClient] Call api:malloc export_desc buffer failed, len:%zu bytes", n);
156	  HIXL_DISMISSABLE_GUARD(buf_guard, ([buf]() { std::free(buf); }));
157	  uint8_t *dst = static_cast<uint8_t *>(buf);
158	  for (size_t i = 0; i < n; ++i) {
159	    HIXL_CHK_BOOL_RET_STATUS(j_export[i].is_number_integer(), hixl::PARAM_INVALID,
160	                             "[HixlClient] export_desc[%zu] is not integer", i);
161	    const int v = j_export[i].get<int>();
162	    HIXL_CHK_BOOL_RET_STATUS(v >= 0 && v <= UINT8_MAX, hixl::PARAM_INVALID,
163	                             "[HixlClient] export_desc[%zu]:%d out of range [0,255]", i, v);
164	    dst[i] = static_cast<uint8_t>(v);
165	  }
166	  desc.export_desc = buf;
167	  desc.export_len = static_cast<uint32_t>(n);
168	  HIXL_DISMISS_GUARD(buf_guard);
169	  return hixl::SUCCESS;
170	}
171	
172	hixl::Status ParseOneMemDesc(const nlohmann::json &item, uint32_t idx, hixl::HixlMemDesc &out) {
173	  try {
174	    if (!item.contains("tag") || !item.contains("export_desc") || !item.contains("mem") || !item["mem"].is_object()) {
175	      HIXL_LOGE(hixl::PARAM_INVALID,
176	                "[HixlClient] GetRemoteMemResp.mem_descs[%u] missing 'tag' / 'export_desc' or 'mem'", idx);
177	      return hixl::PARAM_INVALID;
178	    }
179	    CommMem mem{};
180	    HIXL_CHK_STATUS_RET(ParseMemObject(item["mem"], mem));
181	    out.mem = mem;
182	    out.tag = item["tag"].get<std::string>();
183	    if (item.contains("registered_dev_mem")) {
184	      out.registered_dev_mem = reinterpret_cast<void *>(item["registered_dev_mem"].get<uintptr_t>());
185	    }
186	    return FillExportDescFromJsonField(item["export_desc"], out);
187	  } catch (const nlohmann::json::exception &e) {
188	    HIXL_LOGE(hixl::PARAM_INVALID, "[HixlClient] JSON error in ParseOneMemDesc[%u]: %s", idx, e.what());
189	    return hixl::PARAM_INVALID;
190	  } catch (...) {
191	    HIXL_LOGE(hixl::FAILED, "[HixlClient] Unknown error in ParseOneMemDesc[%u]", idx);
192	    return hixl::FAILED;
193	  }
194	}
195	
196	hixl::Status ParseMemDescsArray(const nlohmann::json &arr, std::vector<hixl::HixlMemDesc> &mem_descs) {
197	  const uint32_t mem_num = static_cast<uint32_t>(arr.size());
198	  HIXL_LOGD("[HixlClient] Parsing mem_descs array, size: %u", mem_num);
199	  HIXL_CHK_BOOL_RET_STATUS(mem_num <= kMaxGetRemoteMemNum, hixl::PARAM_INVALID,
200	                           "[HixlClient] mem_num too large in GetRemoteMemResp, mem_num=%u, max=%u", mem_num,
201	                           kMaxUserRemoteMemNum);
202	
203	  mem_descs.clear();
204	  mem_descs.reserve(mem_num);
205	
206	  for (uint32_t i = 0; i < mem_num; ++i) {
207	    hixl::HixlMemDesc desc{};
208	    hixl::Status ret = ParseOneMemDesc(arr[i], i, desc);
209	    if (ret != hixl::SUCCESS) {
210	      if (desc.export_desc != nullptr) {
211	        std::free(desc.export_desc);
212	        desc.export_desc = nullptr;
213	      }
214	      FreeExportDesc(mem_descs);
215	      return ret;
216	    }
217	    mem_descs.emplace_back(std::move(desc));
218	  }
219	  return hixl::SUCCESS;
220	}
221	
222	hixl::Status ParseGetRemoteMemJson(const char *json_ptr, size_t json_len, std::vector<hixl::HixlMemDesc> &mem_descs) {
223	  HIXL_LOGD("[HixlClient] Parsing JSON from memory address %p, len %zu", json_ptr, json_len);
224	  nlohmann::json j;
225	  try {
226	    j = nlohmann::json::parse(json_ptr, json_ptr + json_len);
227	  } catch (const nlohmann::json::exception &e) {
228	    HIXL_LOGE(hixl::PARAM_INVALID, "[HixlClient] Failed to parse GetRemoteMemResp json, exception:%s", e.what());
229	    return hixl::PARAM_INVALID;
230	  } catch (...) {
231	    HIXL_LOGE(hixl::FAILED, "[HixlClient] Unknown error during json parse");
232	    return hixl::FAILED;
233	  }
234	
235	  const nlohmann::json *arr = nullptr;
236	  HIXL_CHK_STATUS_RET(ParseResultAndGetArray(j, arr));
237	
238	  return ParseMemDescsArray(*arr, mem_descs);
239	}
240	}  // namespace
241	
242	namespace hixl {
243	
244	Status MemMsgHandler::SendGetRemoteMemRequest(int32_t socket, uint64_t endpoint_handle, uint32_t timeout_ms) {
245	  HIXL_EVENT("[HixlClient] SendGetRemoteMemRequest start. socket: %d, endpoint_handle: %lu", socket, endpoint_handle);
246	  (void)timeout_ms;
247	  CtrlMsgHeader header{};
248	  header.magic = kMagicNumber;
249	  header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType) + sizeof(GetRemoteMemReq));
250	
251	  CtrlMsgType msg_type = CtrlMsgType::kGetRemoteMemReq;
252	
253	  GetRemoteMemReq body{};
254	  body.dst_ep_handle = endpoint_handle;
255	
256	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(socket, &header, static_cast<uint64_t>(sizeof(header))));
257	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(socket, &msg_type, static_cast<uint64_t>(sizeof(msg_type))));
258	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(socket, &body, static_cast<uint64_t>(sizeof(body))));
259	  HIXL_EVENT("[HixlClient] SendGetRemoteMemRequest success. fd=%d", socket);
260	  return SUCCESS;
261	}
262	
263	Status MemMsgHandler::RecvGetRemoteMemResponse(int32_t socket, std::vector<HixlMemDesc> &mem_descs,
264	                                               uint32_t timeout_ms) {
265	  HIXL_EVENT("[HixlClient] RecvGetRemoteMemResponse start. socket: %d, timeout_ms: %u ms", socket, timeout_ms);
266	  uint64_t body_size = 0;
267	  HIXL_CHK_STATUS_RET(RecvAndCheckHeader(socket, body_size, timeout_ms));
268	  std::vector<uint8_t> body;
269	  HIXL_CHK_STATUS_RET(RecvBody(socket, body_size, body, timeout_ms));
270	  CtrlMsgType msg_type{};
271	  const char *json_ptr = nullptr;
272	  size_t json_len = 0;
273	  HIXL_CHK_STATUS_RET(ExtractTypeAndJsonPtr(body, msg_type, json_ptr, json_len));
274	  Status ret = ParseGetRemoteMemJson(json_ptr, json_len, mem_descs);
275	  if (ret == SUCCESS) {
276	    HIXL_EVENT("[HixlClient] RecvGetRemoteMemResponse success. Parsed %zu mem descriptors.", mem_descs.size());
277	  } else {
278	    HIXL_LOGE(ret, "[HixlClient] RecvGetRemoteMemResponse failed during parsing.");
279	  }
280	  return ret;
281	}
