21	Status MsgReceiver::RecvHeader() {
22	  CtrlMsgHeader *header = nullptr;
23	  header = reinterpret_cast<CtrlMsgHeader *>(recv_buffer_.data());
24	  HIXL_CHK_BOOL_RET_STATUS(header->magic == kMagicNumber, PARAM_INVALID, "Invalid magic number:%u received.",
25	                           header->magic);
26	  HIXL_CHK_BOOL_RET_STATUS(header->body_size >= sizeof(CtrlMsgType), PARAM_INVALID,
27	                           "Invalid body size:%lu received, must >= %zu.", header->body_size, sizeof(CtrlMsgType));
28	  expected_size_ = header->body_size;
29	  HIXL_CHK_BOOL_RET_STATUS(expected_size_ <= kMaxBodySizeInBytes, PARAM_INVALID,
30	                           "Invalid body size:%zu received, must <= %zu.", expected_size_, kMaxBodySizeInBytes);
31	  recv_state_ = RecvState::WAITING_FOR_BODY;
32	  if (received_size_ > sizeof(CtrlMsgHeader)) {
33	    size_t remaining = received_size_ - sizeof(CtrlMsgHeader);
34	    const size_t buffer_size = recv_buffer_.size();
35	    auto ret = memmove_s(recv_buffer_.data(), buffer_size, recv_buffer_.data() + sizeof(CtrlMsgHeader), remaining);
36	    HIXL_CHK_BOOL_RET_STATUS(ret == EOK, FAILED,
37	                             "Call api:memmove_s failed, ret:%d, dst_addr:%p, dst_max:%zu, src_addr:%p, count:%zu",
38	                             static_cast<int32_t>(ret), recv_buffer_.data(), buffer_size,
39	                             recv_buffer_.data() + sizeof(CtrlMsgHeader), remaining);
40	    received_size_ = remaining;
41	  } else {
42	    received_size_ = 0U;
43	  }
44	  return SUCCESS;
45	}
