47	bool MsgReceiver::CheckRecv(ssize_t recv_size) const {
48	  if (recv_size < 0) {
49	    if (errno != EAGAIN && errno != EWOULDBLOCK && errno != EINTR) {
50	      HIXL_LOGE(FAILED, "Failed to recv message, fd:%d, errno:%s", fd_, strerror(errno));
51	    }
52	    return false;
53	  }
54	  if (recv_size == 0) {
55	    HIXL_LOGI("Peer closed connection, fd:%d.", fd_);
56	    return false;
57	  }
58	  return true;
59	}
