61	Status MsgReceiver::IRecv(std::vector<CtrlMsgPtr> &msgs) {
62	  if (recv_buffer_.size() < received_size_ + kRecvChunkSizeInBytes) {
63	    recv_buffer_.resize(received_size_ + kRecvChunkSizeInBytes);
64	  }
65	  auto buffer = recv_buffer_.data() + received_size_;
66	  auto buffer_size = recv_buffer_.size() - received_size_;
67	  ssize_t n = recv(fd_, buffer, buffer_size, 0);
68	  if (!CheckRecv(n)) {
69	    return SUCCESS;
70	  }
71	  received_size_ += static_cast<size_t>(n);
72	  while (true) {
73	    if (recv_state_ == RecvState::WAITING_FOR_HEADER) {
74	      if (received_size_ < sizeof(CtrlMsgHeader)) {
75	        break;
76	      }
77	      HIXL_CHK_STATUS_RET(RecvHeader(), "Failed to recv header");
78	    }
79	    if (recv_state_ == RecvState::WAITING_FOR_BODY) {
80	      if (received_size_ < expected_size_) {
81	        break;
82	      }
83	      auto ctrl_msg = MakeShared<CtrlMsg>();
84	      HIXL_CHECK_NOTNULL(ctrl_msg);
85	      ctrl_msg->msg_type = *reinterpret_cast<CtrlMsgType *>(recv_buffer_.data());
86	      ctrl_msg->msg = std::string(recv_buffer_.data() + sizeof(CtrlMsgType), expected_size_ - sizeof(CtrlMsgType));
87	      msgs.emplace_back(ctrl_msg);
88	      HIXL_LOGI("[HixlServer] recv ctrl msg, msg type:%d, msg body size:%zu", static_cast<int32_t>(ctrl_msg->msg_type),
89	                ctrl_msg->msg.size());
90	      if (received_size_ > expected_size_) {
91	        size_t remaining = received_size_ - expected_size_;
92	        const size_t buffer_size = recv_buffer_.size();
93	        auto ret = memmove_s(recv_buffer_.data(), buffer_size, recv_buffer_.data() + expected_size_, remaining);
94	        HIXL_CHK_BOOL_RET_STATUS(ret == EOK, FAILED,
95	                                 "Call api:memmove_s failed, ret:%d, dst_addr:%p, dst_max:%zu, src_addr:%p, count:%zu",
96	                                 static_cast<int32_t>(ret), recv_buffer_.data(), buffer_size,
97	                                 recv_buffer_.data() + expected_size_, remaining);
98	        received_size_ = remaining;
99	        recv_state_ = RecvState::WAITING_FOR_HEADER;
100	      } else {
101	        received_size_ = 0U;
102	        recv_state_ = RecvState::WAITING_FOR_HEADER;
103	        break;
104	      }
105	    }
106	  }
107	  return SUCCESS;
108	}
