114	Status HixlCSServer::InitTransFinishedFlag() {
115	  std::vector<EndpointPtr> host_endpoints;
116	  std::vector<EndpointPtr> device_endpoints;
117	  bool has_non_hccs_device_ep = false;
118	  for (auto handle : endpoint_store_.GetAllEndpointHandles()) {
119	    auto endpoint = endpoint_store_.GetEndpoint(handle);
120	    if (endpoint == nullptr) {
121	      continue;
122	    }
123	    const auto &desc = endpoint->GetEndpoint();
124	    if (desc.loc.locType == ENDPOINT_LOC_TYPE_HOST) {
125	      host_endpoints.emplace_back(std::move(endpoint));
126	    } else if (desc.loc.locType == ENDPOINT_LOC_TYPE_DEVICE) {
127	      if (desc.protocol != COMM_PROTOCOL_HCCS) {
128	        has_non_hccs_device_ep = true;
129	      }
130	      device_endpoints.emplace_back(std::move(endpoint));
131	    }
132	  }
133	  if (!host_endpoints.empty()) {
134	    HIXL_CHK_STATUS_RET(RegisterHostTransFinishedFlag(host_endpoints), "Failed to reg HOST trans finished flag");
135	  }
136	  if (!device_endpoints.empty()) {
137	    HIXL_CHK_STATUS_RET(RegisterDeviceTransFinishedFlag(device_endpoints, has_non_hccs_device_ep),
138	                        "Failed to reg DEVICE trans finished flag");
139	  }
140	  return SUCCESS;
141	}
