143	Status HixlCSServer::RegisterHostTransFinishedFlag(const std::vector<EndpointPtr> &host_endpoints) {
144	  void *host_flag = nullptr;
145	  int64_t page_size = sysconf(_SC_PAGESIZE);
146	  HIXL_CHK_BOOL_RET_STATUS(page_size > 0, FAILED, "sysconf(_SC_PAGESIZE) failed, errno=%d, errmsg=%s", errno,
147	                           strerror(errno));
148	  size_t align_size = static_cast<size_t>(page_size);
149	  // Register host mem addr need aligned by page size.
150	  int ret = posix_memalign(&host_flag, align_size, sizeof(int64_t));
151	  HIXL_CHK_BOOL_RET_STATUS(ret == 0 && host_flag != nullptr, FAILED,
152	                           "HOST trans finished flag posix_memalign failed, ret:%d, page_size=%zu, alloc size=%zu.",
153	                           ret, align_size, sizeof(int64_t));
154	  HIXL_DISMISSABLE_GUARD(host_flag_guard, ([host_flag]() { free(host_flag); }));
155	  *static_cast<int64_t *>(host_flag) = 1;
156	  CommMem mem{};
157	  mem.type = COMM_MEM_TYPE_HOST;
158	  mem.addr = host_flag;
159	  mem.size = sizeof(int64_t);
160	  for (const auto &endpoint : host_endpoints) {
161	    MemHandle ep_mem_handle = nullptr;
162	    HIXL_CHK_STATUS_RET(endpoint->RegisterMem(kTransFlagNameHost, mem, ep_mem_handle),
163	                        "Failed to reg HOST trans finished flag");
164	  }
165	  host_trans_flag_ = host_flag;
166	  HIXL_DISMISS_GUARD(host_flag_guard);
167	  return SUCCESS;
