202	                        "Failed to reg DEVICE trans finished flag");
203	  }
204	  dev_trans_flag_ = dev_flag;
205	  HIXL_DISMISS_GUARD(dev_flag_guard);
206	  HIXL_DISMISS_GUARD(pool_rollback);
