211	Status HixlCSServer::Initialize(const EndpointDesc *endpoint_list, uint32_t list_num) {
212	  HIXL_CHECK_NOTNULL(endpoint_list);
213	  HIXL_CHK_BOOL_RET_STATUS(list_num > 0, PARAM_INVALID, "endpoint list num:%u is invalid, must > 0", list_num);
214	  const bool ub_ctp_endpoints_all_device = AreUbCtpEndpointsAllDevice(endpoint_list, list_num);
215	  for (uint32_t i = 0U; i < list_num; ++i) {
216	    EndpointHandle handle = nullptr;
217	    HIXL_CHK_STATUS_RET(
218	        endpoint_store_.CreateEndpoint(endpoint_list[i], handle,
219	                                       NeedServerHostVaMapping(endpoint_list[i], ub_ctp_endpoints_all_device)),
220	        "Failed to create endpoint, index:%u, %s", i, EndpointToString(endpoint_list[i]).c_str());
221	  }
222	  msg_handler_.RegisterMsgProcessor(CtrlMsgType::kMatchEndpointReq,
223	                                    [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
224	                                      return this->MatchEndpointMsg(fd, msg, msg_len);
225	                                    });
226	  msg_handler_.RegisterMsgProcessor(CtrlMsgType::kCreateChannelReq,
227	                                    [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
228	                                      return this->CreateChannel(fd, msg, msg_len);
229	                                    });
230	  msg_handler_.RegisterMsgProcessor(
231	      CtrlMsgType::kGetRemoteMemReq,
232	      [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status { return this->ExportMem(fd, msg, msg_len); });
233	  msg_handler_.RegisterMsgProcessor(CtrlMsgType::kDestroyChannelReq,
234	                                    [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
235	                                      return this->DestroyChannel(fd, msg, msg_len);
236	                                    });
237	  CtrlMsgPlugin::Initialize();
238	  HIXL_CHK_STATUS_RET(msg_handler_.Initialize(), "Failed to initialize msg handler");
239	  HIXL_CHK_STATUS_RET(InitTransFinishedFlag(), "Failed to init trans finished flag");
240	  HIXL_EVENT("[HixlServer] init success, endpoint_list_num:%u", list_num);
241	  return SUCCESS;
242	}
