244	Status HixlCSServer::DestroyChannel(int32_t fd, const char *msg, uint64_t msg_len) {
245	  (void)msg;
246	  (void)msg_len;
247	  std::lock_guard<std::mutex> lock(chn_mutex_);
248	  auto it = channels_.find(fd);
249	  if (it != channels_.end()) {
250	    auto handle = it->second.endpoint_handle;
251	    auto ep = endpoint_store_.GetEndpoint(handle);
252	    if (ep != nullptr) {
253	      HIXL_CHK_STATUS(ep->DestroyChannel(it->second.channel_handle),
254	                      "Failed to destroy channel, fd:%d, endpoint_handle:%p, channel_handle:0x%lx", fd, handle,
255	                      it->second.channel_handle);
256	    }
257	    channels_.erase(it);
258	  }
259	  return SUCCESS;
260	}
