318	Status HixlCSServer::RegisterMem(const char *mem_tag, const CommMem *mem, MemHandle *mem_handle) {
319	  auto ctx_guard = GetContextGuard();
320	  (void)ctx_guard;
321	  HIXL_EVENT("[HixlServer] register mem start, addr:%p, size:%lu, type:%d", mem->addr, mem->size,
322	             static_cast<int32_t>(mem->type));
323	  auto all_handles = endpoint_store_.GetAllEndpointHandles();
324	  HIXL_CHK_BOOL_RET_STATUS(all_handles.size() > 0, PARAM_INVALID, "no endpoint is available");
325	  bool has_ub_endpoint = false;
326	  for (auto handle : all_handles) {
327	    auto endpoint = endpoint_store_.GetEndpoint(handle);
328	    HIXL_CHECK_NOTNULL(endpoint);
329	    has_ub_endpoint = has_ub_endpoint || IsUbEndpoint(endpoint->GetEndpoint().protocol);
330	  }
331	  HIXL_CHK_BOOL_RET_STATUS(!has_ub_endpoint || IsValidMemType(mem->type), PARAM_INVALID, "invalid mem type:%d",
332	                           static_cast<int32_t>(mem->type));
333	
334	  std::vector<EndpointMemInfo> ep_mem_infos;
335	  for (auto handle : all_handles) {
336	    auto endpoint = endpoint_store_.GetEndpoint(handle);
337	    HIXL_CHECK_NOTNULL(endpoint);
338	    if (!ShouldRegisterEndpointForMem(endpoint, mem->type)) {
339	      continue;
340	    }
341	    MemHandle ep_mem_handle = nullptr;
342	    HIXL_CHK_STATUS_RET(endpoint->RegisterMem(mem_tag, *mem, ep_mem_handle), "Failed to register mem.");
343	    EndpointMemInfo ep_mem_info{};
344	    ep_mem_info.endpoint_handle = handle;
345	    ep_mem_info.mem_handle = ep_mem_handle;
346	    ep_mem_infos.emplace_back(ep_mem_info);
347	  }
348	  HIXL_CHK_BOOL_RET_STATUS(!ep_mem_infos.empty(), PARAM_INVALID, "no endpoint matches mem type:%d for register mem",
349	                           static_cast<int32_t>(mem->type));
350	  *mem_handle = ep_mem_infos[0].mem_handle;
351	  HIXL_EVENT("[HixlServer] register mem success, addr:%p, size:%lu, type:%d, handle:%p", mem->addr, mem->size,
352	             static_cast<int32_t>(mem->type), *mem_handle);
353	  std::lock_guard<std::mutex> lock(reg_mutex_);
354	  reg_mems_[ep_mem_infos[0].mem_handle] = std::move(ep_mem_infos);
355	  return SUCCESS;
356	}
357	
358	Status HixlCSServer::DeregisterMem(MemHandle mem_handle) {
359	  auto ctx_guard = GetContextGuard();
360	  (void)ctx_guard;
361	  HIXL_EVENT("[HixlServer] deregister mem start, handle:%p", mem_handle);
362	  std::lock_guard<std::mutex> lock(reg_mutex_);
363	  auto it = reg_mems_.find(mem_handle);
364	  HIXL_CHK_BOOL_RET_STATUS(it != reg_mems_.cend(), PARAM_INVALID, "mem_handle:%p is not registered", mem_handle);
365	  for (const auto &ep_mem_info : it->second) {
366	    auto endpoint = endpoint_store_.GetEndpoint(ep_mem_info.endpoint_handle);
367	    HIXL_CHECK_NOTNULL(endpoint);
368	    HIXL_CHK_STATUS_RET(endpoint->DeregisterMem(ep_mem_info.mem_handle), "Failed to deregister mem, handle:%p.",
369	                        ep_mem_info.mem_handle);
370	  }
371	  reg_mems_.erase(it);
372	  HIXL_EVENT("[HixlServer] deregister mem success, handle:%p", mem_handle);
373	  return SUCCESS;
374	}
