398	Status HixlCSServer::MatchEndpointMsg(int32_t fd, const char *msg, uint64_t msg_len) const {
399	  HIXL_DISMISSABLE_GUARD(failed, ([fd, this]() {
400	                           MatchEndpointResp resp{};
401	                           resp.result = FAILED;
402	                           HIXL_CHK_STATUS(SendMatchEndpointResp(fd, resp));
403	                         }));
404	  HIXL_CHECK_NOTNULL(msg);
405	  HIXL_CHK_BOOL_RET_STATUS(msg_len == sizeof(MatchEndpointReq), PARAM_INVALID,
406	                           "invalid msg len:%lu of match endpoint, must = %zu", msg_len, sizeof(MatchEndpointReq));
407	  const auto &req = *reinterpret_cast<const MatchEndpointReq *>(msg);
408	  EndpointHandle handle = nullptr;
409	  auto ep = endpoint_store_.MatchEndpoint(req.dst, handle);
410	  MatchEndpointResp resp{};
411	  if (ep == nullptr) {
412	    resp.result = PARAM_INVALID;
413	    HIXL_CHK_STATUS_RET(SendMatchEndpointResp(fd, resp), "Failed to send match endpoint resp");
414	    HIXL_DISMISS_GUARD(failed);
415	    return SUCCESS;
416	  }
417	  uint32_t listen_port = 0U;
418	  if (global_config_.ListenPort().has_value()) {
419	    listen_port = global_config_.ListenPort().value();
420	    ep->SetPort(listen_port);
421	  } else {
422	    auto ret = HcommProxy::EndpointGetListenPort(handle, &listen_port);
423	    if (ret == HCCL_SUCCESS) {
424	      ep->SetPort(listen_port);
425	    } else if (ret == HCCL_E_NOT_SUPPORT) {
426	      HIXL_LOGW("HcommEndpointGetListenPort is not supported.");
427	    }
428	    HIXL_CHK_BOOL_RET_STATUS(ret == HCCL_SUCCESS || ret == HCCL_E_NOT_SUPPORT, FAILED,
429	                             "Call api:HcommEndpointGetListenPort failed, ret:0x%X, ep_handle:%p",
430	                             static_cast<uint32_t>(ret), handle);
431	  }
432	  resp.result = SUCCESS;
433	  resp.dst_ep_handle = static_cast<uint64_t>(reinterpret_cast<uintptr_t>(handle));
434	  resp.port = ep->GetPort();
435	  resp.channel_index = g_next_server_channel_index.fetch_add(1U, std::memory_order_relaxed);
436	  HIXL_CHK_STATUS_RET(SendMatchEndpointResp(fd, resp), "Failed to send match endpoint resp");
437	  HIXL_DISMISS_GUARD(failed);
438	  HIXL_LOGI("SendMatchEndpointResp success, channel_index=%" PRIu64, resp.channel_index);
439	  return SUCCESS;
440	}
