442	Status HixlCSServer::CreateChannel(int32_t fd, const char *msg, uint64_t msg_len) {
443	  HIXL_DISMISSABLE_GUARD(failed, ([fd, this]() {
444	                           CreateChannelResp resp{};
445	                           resp.result = FAILED;
446	                           HIXL_LOGI("SendCreateChannelResp start");
447	                           HIXL_CHK_STATUS(SendCreateChannelResp(fd, resp));
448	                         }));
