451	                           "invalid msg len:%lu of create channel, must = %zu", msg_len, sizeof(CreateChannelReq));
452	  const auto &req = *reinterpret_cast<const CreateChannelReq *>(msg);
453	  HIXL_CHK_BOOL_RET_STATUS(req.qos <= kQosMax, PARAM_INVALID,
454	                           "invalid req qos:%u of create channel, must in range= [%u, %u]", req.qos, kQosMin, kQosMax);
455	  EndpointHandle handle = reinterpret_cast<EndpointHandle>(static_cast<uintptr_t>(req.dst_ep_handle));
456	  auto ep = endpoint_store_.GetEndpoint(handle);
457	  HIXL_CHECK_NOTNULL(ep);
458	  ChannelHandle channel_handle = 0UL;
459	  ChannelDesc channel_desc{};
460	  channel_desc.remote_endpoint = req.src;
461	  channel_desc.tc = req.tc;
462	  channel_desc.sl = req.sl;
463	  channel_desc.retry_cnt = req.retry_cnt;
464	  channel_desc.retry_interval = req.retry_interval;
465	  channel_desc.channel_type = ChannelType::kServer;
466	  channel_desc.channel_index = req.channel_index;
467	  channel_desc.qos = req.qos;
468	  HIXL_CHK_STATUS_RET(ep->CreateChannel(channel_desc, channel_handle, req.timeout_ms), "Failed to create channel");
469	  std::lock_guard<std::mutex> lock(chn_mutex_);
470	  EndpointChannelInfo info{};
471	  info.endpoint_handle = handle;
472	  info.channel_handle = channel_handle;
473	  channels_[fd] = std::move(info);
474	  HIXL_DISMISS_GUARD(failed);
475	  CreateChannelResp resp{};
476	  resp.result = SUCCESS;
477	  HIXL_CHK_STATUS_RET(SendCreateChannelResp(fd, resp), "Failed to send create channel resp");
478	  HIXL_LOGI("CreateChannel success, channel_index=%" PRIu64, req.channel_index);
479	  return SUCCESS;
480	}
