585	void HixlCSServer::CleanupClient(int32_t fd) {
586	  // 清理 channel
587	  std::lock_guard<std::mutex> lock(client_mutex_);
588	  auto it = clients_.find(fd);
589	  if (it != clients_.end()) {
590	    auto msg = MakeShared<CtrlMsg>();
591	    if (msg != nullptr) {
592	      msg->msg_type = CtrlMsgType::kDestroyChannelReq;
593	      msg_handler_.SubmitMsg(fd, msg);
594	    }
595	  }
596	
597	  // 清理 epoll
598	  epoll_ctl(epoll_fd_, EPOLL_CTL_DEL, fd, nullptr);
599	
600	  // 关闭 socket
601	  close(fd);
602	
603	  // 清理客户端记录
604	  clients_.erase(fd);
605	
606	  HIXL_EVENT("[HixlServer] client disconnected, fd:%d cleaned up", fd);
607	}
608	
609	Status HixlCSServer::DoWait() {
610	  struct epoll_event event_infos[kMaxEventsNum];
611	  int32_t event_num = epoll_wait(epoll_fd_, event_infos, kMaxEventsNum, kEpollWaitTimeInMillis);
612	  for (int32_t i = 0; i < event_num; ++i) {
613	    // new connection
614	    int32_t fd = event_infos[i].data.fd;
615	    uint32_t revents = event_infos[i].events;
616	    if (fd == listen_fd_) {
617	      int32_t connect_fd = -1;
618	      HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Accept(listen_fd_, connect_fd), "Failed to accept fd");
619	      HIXL_CHK_STATUS_RET(CtrlMsgPlugin::SetTcpNoDelay(connect_fd), "Failed to set tcp nodelay, fd:%d", connect_fd);
620	      HIXL_CHK_STATUS_RET(CtrlMsgPlugin::SetTcpKeepAlive(connect_fd), "Failed to set tcp keep alive, fd:%d",
621	                          connect_fd);
622	      HIXL_CHK_STATUS_RET(CtrlMsgPlugin::AddFdToEpoll(epoll_fd_, connect_fd), "Failed to add connect fd to epoll");
623	      HIXL_EVENT("[HixlServer] accept socket success, client fd:%d", connect_fd);
624	      auto receiver = MakeShared<MsgReceiver>(connect_fd);
625	      HIXL_CHECK_NOTNULL(receiver);
626	      std::lock_guard<std::mutex> lock(client_mutex_);
627	      clients_[connect_fd] = receiver;
628	    } else {
629	      // 检测客户端断开事件
630	      if ((revents & (EPOLLERR | EPOLLHUP | EPOLLRDHUP)) != 0U) {
631	        HIXL_EVENT("[HixlServer] detected client disconnect event, fd:%d, events:0x%x", fd, revents);
632	        CleanupClient(fd);
633	        continue;
634	      }
635	
636	      // client msg
637	      std::lock_guard<std::mutex> lock(client_mutex_);
638	      auto it = clients_.find(fd);
639	      HIXL_EVENT("[HixlServer] recv socket msg, client fd:%d", fd);
640	      if ((it != clients_.end()) && ((revents & EPOLLIN) != 0U)) {
641	        ProClientMsg(fd, it->second);
642	      }
643	    }
644	  }
645	  return SUCCESS;
646	}
647	}  // namespace hixl
