namespace hixl {
class MsgHandler {
 public:
  ~MsgHandler();
  Status Initialize();
  void Finalize();
  void SubmitMsg(int32_t fd, const CtrlMsgPtr &msg);
  Status RegisterMsgProcessor(CtrlMsgType msg_type, MsgProcessor msg_processor);

 private:
  void HandleMsg();
